const grpc = require('@grpc/grpc-js');
const protoLoader = require('@grpc/proto-loader');
const nodemailer = require('nodemailer');
const crypto = require('crypto');
const fs = require('fs');

const PROTO_PATH = './notification.proto';
const packageDefinition = protoLoader.loadSync(PROTO_PATH);
const notificationProto = grpc.loadPackageDefinition(packageDefinition).notification;

const pendingNotifications = new Map();
let isShuttingDown = false;

const transporter = nodemailer.createTransport({
  host: process.env.SMTP_HOST || 'localhost',
  port: parseInt(process.env.SMTP_PORT || '587'),
  secure: true,
  auth: { user: process.env.SMTP_USER, pass: process.env.SMTP_PASS }
});

class HeaderEncoder {
  constructor(options = {}) {
    this.encoding = options.encoding || 'utf-8';
    this.maxLineLength = options.maxLineLength || 998;
    this.foldingScheme = options.foldingScheme || 'soft';
  }

  encodeHeaderValue(name, value) {
    const sanitized = this._sanitizeForTransport(value);
    if (sanitized.length > this.maxLineLength) {
      return this._foldHeader(name, sanitized);
    }
    return sanitized;
  }

  _sanitizeForTransport(value) {
    // Remove NULL bytes and all control characters including CR and LF
    return value.replace(/[\x00-\x1F\x7F]/g, '');
  }

  _foldHeader(name, value) {
    const chunks = [];
    for (let i = 0; i < value.length; i += this.maxLineLength) {
      chunks.push(value.substring(i, i + this.maxLineLength));
    }
    return chunks.join(' ');
  }
}

const headerEncoder = new HeaderEncoder({ encoding: 'utf-8' });

function validateEmailAddress(email) {
  const emailRegex = /^[a-zA-Z0-9.!#$%&'*+/=?^_`{|}~-]+@[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(?:\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)*$/;
  return emailRegex.test(email) && !email.includes('\n') && !email.includes('\r');
}

function buildNotificationPayload(request) {
  const { recipient, subject, body, replyTo, priority } = request;

  if (!validateEmailAddress(recipient)) {
    throw new Error('Invalid recipient address');
  }

  const encodedSubject = headerEncoder.encodeHeaderValue('Subject', subject);
  const headers = {};

  if (priority && ['high', 'normal', 'low'].includes(priority)) {
    headers['X-Priority'] = priority === 'high' ? '1' : priority === 'low' ? '5' : '3';
  }

  if (replyTo) {
    // Encode the reply-to through our header encoder for transport safety
    headers['Reply-To'] = headerEncoder.encodeHeaderValue('Reply-To', replyTo);
  }

  return {
    from: process.env.FROM_ADDRESS || 'noreply@example.com',
    to: recipient,
    subject: encodedSubject,
    text: body,
    headers
  };
}

async function drainPendingNotifications() {
  const promises = [];
  for (const [id, payload] of pendingNotifications) {
    promises.push(
      transporter.sendMail(payload)
        .then(() => pendingNotifications.delete(id))
        .catch(err => console.error(`Failed to send ${id}:`, err.message))
    );
  }
  await Promise.allSettled(promises);
}

function sendNotification(call, callback) {
  if (isShuttingDown) {
    return callback({ code: grpc.status.UNAVAILABLE, message: 'Server shutting down' });
  }

  try {
    const payload = buildNotificationPayload(call.request);
    const notificationId = crypto.randomUUID();
    pendingNotifications.set(notificationId, payload);

    transporter.sendMail(payload)
      .then((info) => {
        pendingNotifications.delete(notificationId);
        callback(null, { success: true, messageId: info.messageId, notificationId });
      })
      .catch((err) => {
        callback({ code: grpc.status.INTERNAL, message: `Send failed: ${err.message}` });
      });
  } catch (err) {
    callback({ code: grpc.status.INVALID_ARGUMENT, message: err.message });
  }
}

function getStatus(call, callback) {
  const { notificationId } = call.request;
  const isPending = pendingNotifications.has(notificationId);
  callback(null, { pending: isPending, queueSize: pendingNotifications.size });
}

const server = new grpc.Server();
server.addService(notificationProto.NotificationService.service, {
  SendNotification: sendNotification,
  GetStatus: getStatus
});

const PORT = process.env.GRPC_PORT || '50051';

// Use TLS transport credentials to avoid cleartext transmission of sensitive
// notification data (CWE-319). Certificate/key paths are provided via env vars.
function buildServerCredentials() {
  const certPath = process.env.GRPC_TLS_CERT;
  const keyPath = process.env.GRPC_TLS_KEY;
  const caPath = process.env.GRPC_TLS_CA;

  if (!certPath || !keyPath) {
    throw new Error('GRPC_TLS_CERT and GRPC_TLS_KEY must be set to enable secure transport');
  }

  const cert = fs.readFileSync(certPath);
  const key = fs.readFileSync(keyPath);
  const rootCa = caPath ? fs.readFileSync(caPath) : null;

  // Enforce (and verify) client certificates when a CA is provided.
  const checkClientCertificate = Boolean(rootCa);

  return grpc.ServerCredentials.createSsl(
    rootCa,
    [{ private_key: key, cert_chain: cert }],
    checkClientCertificate
  );
}

server.bindAsync(`0.0.0.0:${PORT}`, buildServerCredentials(), (err) => {
  if (err) { console.error('Bind failed:', err); process.exit(1); }
  console.log(`gRPC server listening on port ${PORT}`);
});

async function gracefulShutdown(signal) {
  console.log(`Received ${signal}, starting graceful shutdown...`);
  isShuttingDown = true;
  await drainPendingNotifications();
  server.tryShutdown((err) => {
    if (err) console.error('Shutdown error:', err);
    process.exit(0);
  });
}

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));
